window.PYQ_PAPERS = window.PYQ_PAPERS || {};
window.PYQ_PAPERS['pyq-dec2025'] = [{"id":1,"part":"A","unit":null,"blocks":[{"t":"p","h":"The Sankey diagram shows food preferences of males and females. The widths of the bands are proportional to numbers of persons opting for a given food item."},{"t":"img","src":"data:image/webp;base64,","w":180,"h":162,"alt":"Figure for question 1"},{"t":"p","h":"Which one of the following is an INCORRECT statement about the food preferences?"}],"options":[{"key":"1","text":"Chicken is the second most preferred food in males"},{"key":"2","text":"As compared to males, more females prefer wheat"},{"key":"3","text":"As compared to males, more females prefer mutton and millet"},{"key":"4","text":"Fewer females prefer rice than the total number of males preferring maize and millet"}],"answer":"4"},{"id":2,"part":"A","unit":null,"blocks":[{"t":"p","h":"There is an increase of 30% in the number of people coming to a theatre after reducing the entry fee by 25% per person. How much change is expected in the total earnings?"}],"options":[{"key":"1","text":"2.5% increase"},{"key":"2","text":"2.5% decrease"},{"key":"3","text":"Nil"},{"key":"4","text":"7.5% increase"}],"answer":"2"},{"id":3,"part":"A","unit":null,"blocks":[{"t":"p","h":"Suppose the words GATE, FAST, SAND and READ can be written in numbers as 2938, 6921, 0798 and 5917, but not necessarily in that order. The positions of the letters in a word and the corresponding digits in the respective number are the same. Then the word NEGATE will be written as:"}],"options":[{"key":"1","text":"716921"},{"key":"2","text":"380798"},{"key":"3","text":"375917"},{"key":"4","text":"891217"}],"answer":"3"},{"id":4,"part":"A","unit":null,"blocks":[{"t":"p","h":"A person borrowed Rs. 2500/- for 2 years, and Rs. 2000/- for 3 years, with the same simple interest rate. If he paid a total of Rs. 550/- as interest, then the annual rate of interest was:"}],"options":[{"key":"1","text":"10%"},{"key":"2","text":"2%"},{"key":"3","text":"5%"},{"key":"4","text":"8%"}],"answer":"3"},{"id":5,"part":"A","unit":null,"blocks":[{"t":"p","h":"A father said to his son, \"I was as old as you are when I became your father\". If the current age of father is 52 years, the age of son after 10 years will be:"}],"options":[{"key":"1","text":"26 years"},{"key":"2","text":"36 years"},{"key":"3","text":"20 years"},{"key":"4","text":"40 years"}],"answer":"2"},{"id":6,"part":"A","unit":null,"blocks":[{"t":"p","h":"Numbers of seats for Mathematics, Physics and Biology in a college are in the ratio 2:3:4. What will be the respective ratio if the seats for each subject are increased by 50%?"}],"options":[{"key":"1","text":"1:1:1"},{"key":"2","text":"2:3:4"},{"key":"3","text":"4:3:2"},{"key":"4","text":"3:2:4"}],"answer":"2"},{"id":7,"part":"A","unit":null,"blocks":[{"t":"p","h":"The following ternary figure shows the marks obtained by students A, B and C in an exam of 100 marks. Here, C received 10 marks in Physics, 50 marks in Chemistry and 40 marks in Mathematics."},{"t":"img","src":"data:image/webp;base64,","w":275,"h":191,"alt":"Figure for question 7"},{"t":"p","h":"Which one of the following is CORRECT?"}],"options":[{"key":"1","text":"A's marks in Chemistry are more than C's marks in Physics"},{"key":"2","text":"B has scored equal in Mathematics and Physics"},{"key":"3","text":"A has scored 20 in Chemistry"},{"key":"4","text":"A has scored 80 in Chemistry"}],"answer":"2"},{"id":8,"part":"A","unit":null,"blocks":[{"t":"p","h":"Restaurants A, B, C, and D give the following offers:<br>A: one mocktail free for every two purchased<br>B: one mocktail free for every three purchased<br>C: two mocktails free for every six purchased<br>D: 30% discount on each mocktail<br>If all have the same marked price, in which restaurant would you pay the least if you drank eight mocktails?"}],"options":[{"key":"1","text":"A"},{"key":"2","text":"B"},{"key":"3","text":"C"},{"key":"4","text":"D"}],"answer":"4"},{"id":9,"part":"A","unit":null,"blocks":[{"t":"p","h":"Sachin sees one-fourth of his body (height) when he stands in front of a vertical mirror at a distance of 20 cm from it. How much of his body will he see if he steps back and stands 40 cm from the mirror?"}],"options":[{"key":"1","text":"half"},{"key":"2","text":"one-fourth"},{"key":"3","text":"one-eighth"},{"key":"4","text":"full"}],"answer":"2"},{"id":10,"part":"A","unit":null,"blocks":[{"t":"p","h":"The pie charts show placement percentages of graduates of five different subjects for two consecutive years:"},{"t":"img","src":"data:image/webp;base64,","w":287,"h":127,"alt":"Figure for question 10"},{"t":"p","h":"In the year 2024, the number of Maths students who got placed was double that of the previous year. Which of the following is the closest to the percentage change in the number of Life Sciences students placed in the year 2024?"}],"options":[{"key":"1","text":"decreased by 1%"},{"key":"2","text":"increased by 50%"},{"key":"3","text":"decreased by 50%"},{"key":"4","text":"increased by 20%"}],"answer":"2"},{"id":11,"part":"A","unit":null,"blocks":[{"t":"p","h":"The unit's place digit is half the ten's place digit in a two-digit number N. If we swap the digits, the number gets reduced by 18. The number N is:"}],"options":[{"key":"1","text":"24"},{"key":"2","text":"42"},{"key":"3","text":"48"},{"key":"4","text":"84"}],"answer":"2"},{"id":12,"part":"A","unit":null,"blocks":[{"t":"p","h":"A boatman on a bank of a river has to carry a dog, a cat and a container full of milk to the other bank in a boat, one at a time. The cat cannot be left alone with the milk or with the dog on either bank. What is the minimum number of times the boatman has to cross the river to carry all to the other bank?"}],"options":[{"key":"1","text":"3"},{"key":"2","text":"5"},{"key":"3","text":"7"},{"key":"4","text":"8"}],"answer":"3"},{"id":13,"part":"A","unit":null,"blocks":[{"t":"p","h":"With a certain set of diameters, a tractor's front wheels make 2 revolutions (revs) for every 1 revolution of the rear wheels. The effect of changing wheel diameter(s) is shown in the following plot:"},{"t":"img","src":"data:image/webp;base64,","w":287,"h":166,"alt":"Figure for question 13"},{"t":"p","h":"In this context, which of the following statements is CORRECT?"}],"options":[{"key":"1","text":"Only the rear wheel diameter is decreased"},{"key":"2","text":"Both the rear and front wheel diameters are decreased equally"},{"key":"3","text":"Both the rear and front wheel diameters are increased equally"},{"key":"4","text":"The rear wheel diameter decreased, and the front wheel diameter increased equally"}],"answer":"3"},{"id":14,"part":"A","unit":null,"blocks":[{"t":"p","h":"The following bus schedule is seen at a bus stop located somewhere in between town A and town B:<br>• Town A - 00:10, then every 20 mins<br>• Town B - 00:15, then every 20 mins<br>If a person arrives at this bus stop at some random time, the probability that the next bus is for town B is:"}],"options":[{"key":"1","text":"1/2"},{"key":"2","text":"1/4"},{"key":"3","text":"1/3"},{"key":"4","text":"3/4"}],"answer":"2"},{"id":15,"part":"A","unit":null,"blocks":[{"t":"p","h":"An auditorium has 8 seats in the first row, with every row to follow having 4 more seats than its preceding row. The total capacity is 416. What is the minimum number of rows needed to seat 150 people?"}],"options":[{"key":"1","text":"8"},{"key":"2","text":"5"},{"key":"3","text":"3"},{"key":"4","text":"2"}],"answer":"3"},{"id":16,"part":"A","unit":null,"blocks":[{"t":"p","h":"With only one match, between teams B and C, remaining in a tournament where each win fetches two points and a loss none, team A observes that they will become champions with more points than any other team if B wins, but not necessarily if B loses. Then:"}],"options":[{"key":"1","text":"A is leading B by one point"},{"key":"2","text":"B is leading C by one point"},{"key":"3","text":"B is leading C by at least two points"},{"key":"4","text":"A is leading C by at most two points"}],"answer":"4"},{"id":17,"part":"A","unit":null,"blocks":[{"t":"p","h":"Consider the following information regarding a 3-digit PIN:"},{"t":"tbl","cls":"pin","rowHead":false,"head":[],"rows":[["6","8","9","→ One number is correct and correctly placed"],["7","3","8","→ Nothing is correct"],["9","0","6","→ Two numbers correct but wrongly placed"],["6","1","5","→ One number is correct but wrongly placed"],["7","8","0","→ One number is correct but wrongly placed"]]}],"options":[{"key":"1","text":"059"},{"key":"2","text":"601"},{"key":"3","text":"590"},{"key":"4","text":"859"}],"answer":"1"},{"id":18,"part":"A","unit":null,"blocks":[{"t":"p","h":"A box contains 20 black, 22 white, and 24 red socks. If a person draws socks at random one by one without looking, what is the minimum number of socks she must pick to be certain of having at least one pair of black socks?"}],"options":[{"key":"1","text":"3"},{"key":"2","text":"4"},{"key":"3","text":"44"},{"key":"4","text":"48"}],"answer":"4"},{"id":19,"part":"A","unit":null,"blocks":[{"t":"p","h":"A cellphone tower with signals reaching up to 500 m is set up on a conical hill of height 1.5 km and base radius 2 km. Assuming the tower's height to be negligible compared to the hill, the area served by the tower in Km² is (the area of the curved surface of a right circular cone is π x base radius x slant height ):"}],"options":[{"key":"1","text":"0.2π"},{"key":"2","text":"0.25π"},{"key":"3","text":"4π"},{"key":"4","text":"5π"}],"answer":"1"},{"id":20,"part":"A","unit":null,"blocks":[{"t":"p","h":"Suppose a tap mixes hot water and cold water in a ratio that depends linearly on the proportion of opening. Water out of the tap has temperature 40°C when the tap is half-open, and at 30°C when it is three-fourths open. To get water at 50°C, the tap should be ______:"}],"options":[{"key":"1","text":"one-eighth open"},{"key":"2","text":"one-fourth open"},{"key":"3","text":"three-eighths open"},{"key":"4","text":"five-eighths open"}],"answer":"2"},{"id":21,"part":"B","unit":1,"blocks":[{"t":"p","h":"Given below are pairs of sugars.<br>A. D-glucose and D-fructose<br>B. D-galactose and D-glucose<br>C. α-D-glucose and β-D-glucose<br>D. D-ribose and D-ribulose<br>Which one of the following options represents the correct combination of anomer and epimer pairs, respectively?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"B and D"},{"key":"3","text":"C and B"},{"key":"4","text":"A and D"}],"answer":"3"},{"id":22,"part":"B","unit":1,"blocks":[{"t":"p","h":"Which one of the following enzymes catalyzes the biochemical reaction given below?"},{"t":"img","src":"data:image/webp;base64,","w":287,"h":121,"alt":"Figure for question 22"}],"options":[{"key":"1","text":"Phosphoenolpyruvate mutase"},{"key":"2","text":"Phosphoglycerate kinase"},{"key":"3","text":"Pyruvate dehydrogenase phosphatase"},{"key":"4","text":"Bis-phosphoglycerate mutase"}],"answer":"4"},{"id":23,"part":"B","unit":1,"blocks":[{"t":"p","h":"Which one of the following corresponds to the angle of rotation per residue in a 3<sub>10</sub> helix and 3.6<sub>13</sub> helix, respectively?"}],"options":[{"key":"1","text":"100° and 120°"},{"key":"2","text":"30° and 60°"},{"key":"3","text":"60° and 30°"},{"key":"4","text":"120° and 100°"}],"answer":"4"},{"id":24,"part":"B","unit":1,"blocks":[{"t":"p","h":"Which one of the following vitamins contains a transition metal ion as a part of its structure?"}],"options":[{"key":"1","text":"Vitamin C"},{"key":"2","text":"Vitamin D3"},{"key":"3","text":"Vitamin B12"},{"key":"4","text":"Vitamin E"}],"answer":"3"},{"id":25,"part":"B","unit":9,"blocks":[{"t":"p","h":"Which one of the following is NOT a disease caused by a virus?"}],"options":[{"key":"1","text":"Small pox"},{"key":"2","text":"Tetanus"},{"key":"3","text":"Rubella"},{"key":"4","text":"Measles"}],"answer":"2"},{"id":26,"part":"B","unit":3,"blocks":[{"t":"p","h":"Which one of the following histone marks is NOT an indicator of heterochromatin?"}],"options":[{"key":"1","text":"H3K9 trimethylation"},{"key":"2","text":"MacroH2A"},{"key":"3","text":"H2AX"},{"key":"4","text":"H4K20 trimethylation"}],"answer":"3"},{"id":27,"part":"B","unit":2,"blocks":[{"t":"p","h":"Which one of the following events are likely to result in delayed or defective cytokinesis?"}],"options":[{"key":"1","text":"Stabilization of mitotic cyclins"},{"key":"2","text":"Activation of formin and myosin II"},{"key":"3","text":"Stimulation of RhoA by centralspindlin"},{"key":"4","text":"Activation of RhoA by Rho-GEF"}],"answer":"1"},{"id":28,"part":"B","unit":3,"blocks":[{"t":"p","h":"The cytosolic proteins, Ras and Rab, are anchored to the cytosolic face of the plasma membrane by prenylation. Prenylation typically occurs at which amino acid of the protein?"}],"options":[{"key":"1","text":"Cysteine residue at or near the C-terminus"},{"key":"2","text":"Cysteine residue at or near the N-terminus"},{"key":"3","text":"Glycine residue at or near the C-terminus"},{"key":"4","text":"Glycine residue at or near the N-terminus"}],"answer":"1"},{"id":29,"part":"B","unit":3,"blocks":[{"t":"p","h":"Which one of the enzymatic activities is NOT present in bacterial RecA?"}],"options":[{"key":"1","text":"ATP hydrolysis activity"},{"key":"2","text":"Strand-exchange activity"},{"key":"3","text":"Nucleolytic activity"},{"key":"4","text":"Proteolytic activity"}],"answer":"3"},{"id":30,"part":"B","unit":3,"blocks":[{"t":"p","h":"Which one of the following statements correctly describes the role of Proliferating Cell Nuclear Antigen (PCNA) in eukaryotic DNA replication?"}],"options":[{"key":"1","text":"It catalyzes RNA primer synthesis."},{"key":"2","text":"It acts as a sliding clamp that increases DNA polymerase processivity."},{"key":"3","text":"It removes RNA primers from Okazaki fragments."},{"key":"4","text":"It unwinds parental DNA."}],"answer":"2"},{"id":31,"part":"B","unit":3,"blocks":[{"t":"p","h":"An antibiotic, that mimics aminoacyl-tRNAs, gets incorporated into the polypeptide chain and prematurely terminates elongation. The following statements are made based on this observation:<br>A. It enters the ribosome through the A-site.<br>B. It enters the ribosome through the P-site.<br>C. A part of its structure resembles the carboxy terminus of amino acids and is available for making a peptide bond.<br>D. A part of its structure resembles the amino terminus of amino acids and is available for making a peptide bond.<br>Which one of the following options represents all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"A and D"},{"key":"3","text":"B and D"},{"key":"4","text":"A and C"}],"answer":"2"},{"id":32,"part":"B","unit":3,"blocks":[{"t":"p","h":"Yeast gene Y has an mRNA with the structure shown below. Both the upstream open reading frame (uORF) and the coding region of gene Y have start and stop codons."},{"t":"img","src":"data:image/webp;base64,","w":287,"h":95,"alt":"Figure for question 32"},{"t":"p","h":"Which one of the following will you remove to maximize translation of gene Y?"}],"options":[{"key":"1","text":"Cap"},{"key":"2","text":"Start codon of the uORF"},{"key":"3","text":"Stop codon of the uORF"},{"key":"4","text":"Poly(A) tail"}],"answer":"2"},{"id":33,"part":"B","unit":4,"blocks":[{"t":"p","h":"Which one of the following statements is FALSE regarding how retroviruses and DNA viruses can lead to cancer in host cells?"}],"options":[{"key":"1","text":"Rous sarcoma virus contains an oncogene derived from a host proto-oncogene, which allows it to rapidly induce tumours."},{"key":"2","text":"Slow-acting retroviruses cause cancer by integrating near host proto-oncogenes, activating their expression and leading to cell proliferation."},{"key":"3","text":"DNA viruses can cause cancer if their DNA becomes integrated into the host genome and expresses viral oncogenes, which stimulate cell growth and proliferation."},{"key":"4","text":"Retroviruses cause cancer only by directly mutating host DNA, without the need for integration or activation of proto-oncogenes."}],"answer":"4"},{"id":34,"part":"B","unit":4,"blocks":[{"t":"p","h":"Which one of the following components of the immune system is NOT effective for the clearance of large parasites like worms?"}],"options":[{"key":"1","text":"Basophils"},{"key":"2","text":"Eosinophils"},{"key":"3","text":"NK cells"},{"key":"4","text":"Mast cells"}],"answer":"3"},{"id":35,"part":"B","unit":4,"blocks":[{"t":"p","h":"Which one of the following molecules does NOT directly transduce signals to neighbouring cells?"}],"options":[{"key":"1","text":"Beta catenin"},{"key":"2","text":"Connexin"},{"key":"3","text":"BMP7"},{"key":"4","text":"Dopamine"}],"answer":"1"},{"id":36,"part":"B","unit":6,"blocks":[{"t":"p","h":"Choose the INCORRECT statement regarding the synthesis of reactive oxygen species (ROS) upon pathogen infection in plants."}],"options":[{"key":"1","text":"Plasma membrane-spanning NADPH oxidase is involved in the synthesis of ROS."},{"key":"2","text":"NADPH oxidases are encoded by respiratory burst oxidase homolog genes in Arabidopsis (Atrboh)."},{"key":"3","text":"Activation of NADPH oxidase does not require the action of calcium-dependent protein kinases (CDPKs)."},{"key":"4","text":"Apoplastic peroxidase enzymes (PRX) are involved in ROS production."}],"answer":"3"},{"id":37,"part":"B","unit":5,"blocks":[{"t":"p","h":"Which one of the following options is the correct sequence of gene expression for successful axis specification in Drosophila?"}],"options":[{"key":"1","text":"Fushi tarazu; giant; hairy; gooseberry"},{"key":"2","text":"Hedgehog; hunchback; runt; paired"},{"key":"3","text":"Odd-skipped; knirps; hairy; armadillo"},{"key":"4","text":"Krüppel; hairy; fushi tarazu; wingless"}],"answer":"4"},{"id":38,"part":"B","unit":5,"blocks":[{"t":"p","h":"In developing mouse brain, when gene yfg is deleted from hippocampal cell-type 'A', the number of neighbouring cell-type 'B' increases by five-fold. From this information. which one of the following statements accurately describes yfg functioning in wildtype 'A' cells?"}],"options":[{"key":"1","text":"It promotes 'B' proliferation."},{"key":"2","text":"It has no role in 'B' proliferation."},{"key":"3","text":"It inhibits 'B' proliferation."},{"key":"4","text":"It induces yfg expression in 'B' cells."}],"answer":"3"},{"id":39,"part":"B","unit":5,"blocks":[{"t":"p","h":"Which one of the following options represents the correct order of events during newt limb regeneration following amputation?"}],"options":[{"key":"1","text":"Wound epidermis formation, remodelling of extracellular matrix, blastema formation, and differentiation"},{"key":"2","text":"Blastema formation, remodelling of extracellular matrix, differentiation and wound epidermis formation"},{"key":"3","text":"Blastema formation, wound epidermis formation, extracellular matrix remodelling and differentiation"},{"key":"4","text":"Extracellular matrix remodelling, wound epiderrnis formation, blastema formation and differentiation"}],"answer":"1"},{"id":40,"part":"B","unit":6,"blocks":[{"t":"p","h":"Which one of the following light treatments (L, light; D, dark) promotes flowering in short-day plants? (Options 1–4 are the four bars in the figure, top to bottom.)"},{"t":"img","src":"data:image/webp;base64,","w":287,"h":148,"alt":"Figure for question 40"}],"options":[{"key":"1","text":"Bar 1 in the figure"},{"key":"2","text":"Bar 2 in the figure"},{"key":"3","text":"Bar 3 in the figure"},{"key":"4","text":"Bar 4 in the figure"}],"answer":"1"},{"id":41,"part":"B","unit":6,"blocks":[{"t":"p","h":"A C3 plant is shifted from 25 °C to 40 °C under full sunlight. Which one of the following is most likely to happen?"}],"options":[{"key":"1","text":"Photorespiration rate decreases, leading to higher productivity."},{"key":"2","text":"Rubisco's oxygenase activity increases, reducing net CO₂ fixation."},{"key":"3","text":"Stomata remain fully open, increasing CO₂ uptake."},{"key":"4","text":"PEP carboxylase activity increases to compensate for CO₂ loss."}],"answer":"2"},{"id":42,"part":"B","unit":6,"blocks":[{"t":"p","h":"Which one of the following pairs is NOT a prokaryote: angiosperm symbiotic pair that can fix atmospheric nitrogen?"}],"options":[{"key":"1","text":"Nostoc and Gunnera"},{"key":"2","text":"Frankia and Casuarina"},{"key":"3","text":"Bradyrhizobium and Parasponia"},{"key":"4","text":"Azolla and Rice"}],"answer":"4"},{"id":43,"part":"B","unit":6,"blocks":[{"t":"p","h":"Sulfur taken by plant roots from the soil undergoes major changes in the oxidation state as it converts from inorganic to biochemically available form. Which one of the following options represents the correct order of the conversion states of sulfur?"}],"options":[{"key":"1","text":"SO₄²⁻ → SO₃²⁻ → S²⁻ → Cys"},{"key":"2","text":"S²⁻ → SO₃²⁻ → SO₄²⁻ → Cys"},{"key":"3","text":"SO₄²⁻ → SO₃²⁻ → S²⁻ → Gln"},{"key":"4","text":"S²⁻ → SO₃²⁻ → SO₄²⁻ → Gln"}],"answer":"1"},{"id":44,"part":"B","unit":6,"blocks":[{"t":"p","h":"Which one of the following is the most appropriate effects of hypoxic pretreatment and acclimation on survival of plants under anoxia?"}],"options":[{"key":"1","text":"Prevention of ethanol fermentation"},{"key":"2","text":"Increase in capacity of roots for lactate efflux"},{"key":"3","text":"Prevention of glucose to lactate conversion"},{"key":"4","text":"Prevention of ethanol diffusion"}],"answer":"2"},{"id":45,"part":"B","unit":4,"blocks":[{"t":"p","h":"Which one of the following metabotropic receptors increases intracellular cAMP level after stimulation by its specific neurotransmitter?"}],"options":[{"key":"1","text":"mGluR5"},{"key":"2","text":"5HT<sub>2A</sub>"},{"key":"3","text":"5HT<sub>4</sub>"},{"key":"4","text":"M<sub>5</sub>"}],"answer":"3"},{"id":46,"part":"B","unit":7,"blocks":[{"t":"p","h":"Which one of the following is NOT involved in the secretion of K⁺ from blood into the tubular fluid by the principal cells of distal tubules?"}],"options":[{"key":"1","text":"Big K⁺ channels (BK)"},{"key":"2","text":"Renal outer medullary K⁺ channels (ROMC)"},{"key":"3","text":"1Na⁺-1K⁺-2Cl⁻ symporter (NKCC2)"},{"key":"4","text":"K⁺/Cl⁻ cotransporter (KCC1)"}],"answer":"3"},{"id":47,"part":"B","unit":7,"blocks":[{"t":"p","h":"Which one of the following is NOT caused by atriopeptins, a family of peptides produced in cardiac atrial tissues?"}],"options":[{"key":"1","text":"Natriuresis"},{"key":"2","text":"Vasoconstriction"},{"key":"3","text":"Diuresis"},{"key":"4","text":"Inhibition of aldosterone secretion"}],"answer":"2"},{"id":48,"part":"B","unit":7,"blocks":[{"t":"p","h":"Which one of the following animals normally exhibit reflex ovulation?"}],"options":[{"key":"1","text":"Rats"},{"key":"2","text":"Monkeys"},{"key":"3","text":"Cats"},{"key":"4","text":"Humans"}],"answer":"3"},{"id":49,"part":"B","unit":8,"blocks":[{"t":"p","h":"Most transposable elements contain flanking terminal inverted repeats. Which one of following options is INCORRECT pertaining to these repeats?"}],"options":[{"key":"1","text":"They are not a part of the transposable element, but are generated during the insertion of the transposable element in the genome."},{"key":"2","text":"They are part of the transposable elements in the genome."},{"key":"3","text":"They move along with the transposable elements in the genome."},{"key":"4","text":"The repeats along with a functional transposase are sufficient for the process of transposition."}],"answer":"1"},{"id":50,"part":"B","unit":3,"blocks":[{"t":"p","h":"Lac repressor binding occurs at the level of:"}],"options":[{"key":"1","text":"mRNA, on the sequence corresponding to the operator region."},{"key":"2","text":"DNA, in the lac operon in the operator region."},{"key":"3","text":"both DNA and RNA, in the sequences corresponding to the operator region."},{"key":"4","text":"ribosomes, during mRNA translation."}],"answer":"2"},{"id":51,"part":"B","unit":8,"blocks":[{"t":"p","h":"A cross is made between two strains of E. coli, Hfr leu⁺ arg⁺ met⁺ and F⁻ leu⁻ arg⁻ met⁻ Str<sup>R</sup> and the mixture is plated on minimal synthetic medium supplemented with streptomycin, arginine and methionine. If the linear organization of the genes are leu-arg-met, which one of the following genotypes is expected to occur with lowest frequency?"}],"options":[{"key":"1","text":"leu⁺ arg⁺ met⁺"},{"key":"2","text":"leu⁺ arg⁺ met⁻"},{"key":"3","text":"leu⁺ arg⁻ met⁻"},{"key":"4","text":"leu⁺ arg⁻ met⁺"}],"answer":"4"},{"id":52,"part":"B","unit":8,"blocks":[{"t":"p","h":"A polydactyly allele shows 60% penetrance and variable expressivity. What would you expect to observe in a family carrying this allele?"}],"options":[{"key":"1","text":"60% of carriers show the trait, and among those who show it, severity varies."},{"key":"2","text":"100% of carriers show the trait but with 60% maximum severity."},{"key":"3","text":"40% of carriers express the trait to the same degree in an identical manner."},{"key":"4","text":"100% of carriers show the trait but the severity varies only in 40% of carriers."}],"answer":"1"},{"id":53,"part":"B","unit":2,"blocks":[{"t":"p","h":"During long-term growth in static liquid culture, Pseudomonas fluorescens diversifies into distinct colony types with the following characteristics: wrinkly spreaders that form biofilms at the oxygen-rich surface, smooth morphs that grow freely in the oxygen-poor bottom layer, and fuzzy types that colonises the intermediate zone. Which one of the following evolutionary processes best explains this ecological diversification?"}],"options":[{"key":"1","text":"Genetic drift resulting in differential microhabitat use"},{"key":"2","text":"Adaptive radiation into different microhabitats"},{"key":"3","text":"Coevolution between the distinct P. fluorescens strains in microhabitats"},{"key":"4","text":"Convergent evolution among unrelated bacterial species"}],"answer":"2"},{"id":54,"part":"B","unit":9,"blocks":[{"t":"p","h":"Which one of the following statements is INCORRECT about the phylogenetic species concept?"}],"options":[{"key":"1","text":"It can be applied to both sexual and asexual organisms and is not dependent on reproductive isolation."},{"key":"2","text":"It relies on objective and statistically testable concepts based on genetic data."},{"key":"3","text":"It is robust to different data sources and produces consistent phylogenies."},{"key":"4","text":"It can suffer from taxonomic inflation."}],"answer":"3"},{"id":55,"part":"B","unit":9,"blocks":[{"t":"p","h":"Which one of the following pairs is analogous and NOT homologous?"}],"options":[{"key":"1","text":"Potato tuber and sweet potato tuber"},{"key":"2","text":"Human arm and whale flipper"},{"key":"3","text":"The thorn of citrus plant and the tendril of a cucurbit plant"},{"key":"4","text":"Flippers of dolphin and fins of fish"}],"answer":"1"},{"id":56,"part":"B","unit":10,"blocks":[{"t":"p","h":"Which one of the following options represents a set of bird species, all of which are found ONLY in India?"}],"options":[{"key":"1","text":"Bluethroat, Amur Falcon, Bar-headed Goose"},{"key":"2","text":"Yellow-throated Bulbul, Forest Owlet, Rufous Babbler"},{"key":"3","text":"Pied Cuckoo, Green Imperial Pigeon, Black Drongo"},{"key":"4","text":"Blue-tailed Bee-eater, Sarus Crane, Red-vented Bulbul"}],"answer":"2"},{"id":57,"part":"B","unit":10,"blocks":[{"t":"p","h":"Which one of the following options is NOT included in the Wildlife (Protection) Amendment Act, 2022?"}],"options":[{"key":"1","text":"Inclusion of a new schedule designating some species as 'vermin'"},{"key":"2","text":"Rationalization of schedules"},{"key":"3","text":"Regulation of invasive alien species"},{"key":"4","text":"Recommendation for implementation of provisions of CITES"}],"answer":"1"},{"id":58,"part":"B","unit":10,"blocks":[{"t":"p","h":"Assimilation Efficiency is calculated as the percentage of the ingested energy that is assimilated by an organism. Which one of the following gut architectures has the lowest assimilation efficiency?"}],"options":[{"key":"1","text":"A monogastric gut with acid enzymes to break down food"},{"key":"2","text":"A ruminant gut that facilitates regurgitation and chewing of cud"},{"key":"3","text":"An avian gut with mechanical grinding in the gizzard"},{"key":"4","text":"Cecal/Hindgut fermentation with enlarged cecum or large intestine"}],"answer":"4"},{"id":59,"part":"B","unit":10,"blocks":[{"t":"p","h":"The resource-ratio hypothesis (R*) of competitive coexistence of species proposed by David Tilman postulates that:"}],"options":[{"key":"1","text":"coexisting species are limited by different resources in the shared resource set."},{"key":"2","text":"shared resources are equally limiting for each competing species."},{"key":"3","text":"species abundances are determined by the ratios of limiting resources for each species."},{"key":"4","text":"the ratio between the resource availability and resource use is constant between competing species."}],"answer":"1"},{"id":60,"part":"B","unit":10,"blocks":[{"t":"p","h":"Which one of the following statements is NOT considered a core principle of conservation biology?"}],"options":[{"key":"1","text":"Conservation efforts should focus on maintaining entire ecosystems, as opposed to only individual species."},{"key":"2","text":"A disruption of species/trophic interactions can create a cascading effect throughout an entire ecosystem."},{"key":"3","text":"Ecosystems should be maintained in their climax state, preventing processes like disturbance and succession."},{"key":"4","text":"Management of an ecosystem should be long term and include many ecological processes and impacts of human activities."}],"answer":"3"},{"id":61,"part":"B","unit":9,"blocks":[{"t":"p","h":"New protein-coding genes sometimes originate when exons from different ancestral genes are combined through recombination events, producing a novel domain architecture within a single polypeptide. This mechanism of generating new genes is called:"}],"options":[{"key":"1","text":"Exon shuffling, in which recombination or transposon-mediated rearrangements join coding regions from separate genes."},{"key":"2","text":"Alternative splicing, in which a single pre-mRNA is processed in multiple ways to yield different transcripts."},{"key":"3","text":"Retroposition, in which an mRNA is reverse-transcribed and inserted elsewhere in the genome."},{"key":"4","text":"Transposon insertion, in which mobile elements insert into genes, occasionally disrupting or modulating their expression."}],"answer":"1"},{"id":62,"part":"B","unit":9,"blocks":[{"t":"p","h":"Gradualism and punctuated equilibrium represent contrasting models of evolutionary change. Which one of the following options best describes these two models?"}],"options":[{"key":"1","text":"Gradualism emphasizes that evolution occurs through long periods of stasis interrupted by sudden, large-scale mutations, while punctuated equilibrium proposes continuous, slow change within species."},{"key":"2","text":"Gradualism and punctuated equilibrium both deny the role of natural selection in shaping evolutionary change."},{"key":"3","text":"Gradualism proposes that evolution proceeds through the steady accumulation of small changes, whereas punctuated equilibrium suggests long periods of evolutionary stability marked by relatively rapid bursts of speciation."},{"key":"4","text":"Both models reject the importance of the fossil record in understanding macroevolutionary patterns."}],"answer":"3"},{"id":63,"part":"B","unit":9,"blocks":[{"t":"p","h":"The circadian rhythm of higher vertebrates is regulated by the:"}],"options":[{"key":"1","text":"suprachiasmatic nucleus."},{"key":"2","text":"cerebral cortex."},{"key":"3","text":"pituitary gland."},{"key":"4","text":"thymus."}],"answer":"1"},{"id":64,"part":"B","unit":9,"blocks":[{"t":"p","h":"Which one of the following is NOT an evolutionary model for mate choice in animals?"}],"options":[{"key":"1","text":"Direct benefit model"},{"key":"2","text":"Good gene model"},{"key":"3","text":"Chase away model"},{"key":"4","text":"Green beard effect"}],"answer":"4"},{"id":65,"part":"B","unit":13,"blocks":[{"t":"p","h":"Which one of the following options is a correct match of plant selection marker genes used for genetic transformation and their properties?"}],"options":[{"key":"1","text":"nptII – Streptomycin resistance"},{"key":"2","text":"Mutant ALS – Imidazolinone resistance"},{"key":"3","text":"aadA – Rifampicin resistance"},{"key":"4","text":"pat – Penicillin resistance"}],"answer":"2"},{"id":66,"part":"B","unit":14,"blocks":[{"t":"p","h":"In the complete blood profile analysis using an automated haematology analyser, the haemoglobin concentration is measured using:"}],"options":[{"key":"1","text":"sedimentation analysis."},{"key":"2","text":"spectrophotometric methods."},{"key":"3","text":"mass spectrometry."},{"key":"4","text":"NMR spectroscopy."}],"answer":"2"},{"id":67,"part":"B","unit":14,"blocks":[{"t":"p","h":"The genome editing tool, CRISPR-Cas9, was developed based on which one of the following natural phenomena?"}],"options":[{"key":"1","text":"An immune response of lower eukaryotes"},{"key":"2","text":"A bacterial defence mechanism"},{"key":"3","text":"A specialised homologous recombination machinery in eukaryotes"},{"key":"4","text":"Transposon insertion machinery in prokaryotes"}],"answer":"2"},{"id":68,"part":"B","unit":13,"blocks":[{"t":"p","h":"Which key feature best differentiates somatic embryogenesis from organogenesis in plant tissue culture?"}],"options":[{"key":"1","text":"Somatic embryogenesis originates from zygotic embryos, while organogenesis originates from vegetative explants."},{"key":"2","text":"Somatic embryos develop bipolar structures (with both shoot and root poles), whereas organogenesis typically produces unipolar structures that require further differentiation."},{"key":"3","text":"Somatic embryogenesis does not require growth regulators, while organogenesis strictly requires an auxin-cytokinin balance."},{"key":"4","text":"In somatic embryogenesis, vascular connections are continuous with the parent tissue, whereas in organogenesis vascular strands remain independent."}],"answer":"2"},{"id":69,"part":"B","unit":3,"blocks":[{"t":"p","h":"Given below is one of the strands of a double-stranded DNA sequence: 5'-ATGCGATGACGATGACGATGACGATGACGAACGATGAGATGG-3' In the absence of any other confounding factors (viz., length, Tm, etc.), which one of the following options represents the primer combination that would amplify the above double- stranded template in a PCR?"}],"options":[{"key":"1","text":"5'-TACGCTACT-3' and 5'-ATGAGATGG-3'"},{"key":"2","text":"5'-ATGCGATGA-3' and 5'-GGTAGAGTA-3'"},{"key":"3","text":"5'-TCATCGCAT-3' and 5'-CCATCTCAT-3'"},{"key":"4","text":"5'-ATGCGATGA-3' and 5'-CCATCTCAT-3'"}],"answer":"4"},{"id":70,"part":"B","unit":14,"blocks":[{"t":"p","h":"Two different antibodies against the same protein were generated. They were named, AB1 and AB2. While AB1 was able to detect the target protein in a western blot, it was unable to detect the protein in ELISA. The opposite was true for AB2. Which one of the following is the most likely reason?"}],"options":[{"key":"1","text":"AB1 detects SDS-bound protein, whereas AB2 detects protein that is not bound to SDS."},{"key":"2","text":"AB1 is unable to cross the cell membrane, whereas AB2 is membrane permeable."},{"key":"3","text":"AB1 detects epitopes on the folded protein, whereas AB2 detects the unfolded epitopes."},{"key":"4","text":"AB1 detects linear epitopes on unfolded protein, but AB2 detects discontinuous epitopes present on the folded protein."}],"answer":"4"},{"id":71,"part":"C","unit":1,"blocks":[{"t":"p","h":"Given below are statements on the citric acid cycle and urea cycle, which have shared metabolic intermediates:<br>A. Oxaloacetate is converted to aspartate.<br>B. Fumarate is a citric acid cycle intermediate.<br>C. Arginosuccinate is cleaved to fumarate and arginine.<br>D. Aspartate combines with citrulline to produce argininosuccinate in the mitochondrial matrix.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and D only"},{"key":"2","text":"B and C only"},{"key":"3","text":"A, C and D"},{"key":"4","text":"A, B and C"}],"answer":"4"},{"id":72,"part":"C","unit":1,"blocks":[{"t":"p","h":"The following experimental observations are made when a small ligand binds with nanomolar affinity in a deep hydrophobic pocket of the partner protein:<br>A. The ligand forms a hydrogen bond with a backbone carbonyl oxygen upon binding.<br>B. Several nonpolar groups in proteins form a hydrophobic network due to the conformational change, leading to the displacement of buried water molecules to the surface.<br>C. A negatively charged side chain of an amino acid located near the binding site is desolvated.<br>D. The desolvated sidechain of an amino acid located near the binding site does not form a salt bridge with the ligand.<br>Which one of the following options represents the combination of all correct statement(s) that explain(s) net stabilisation of the ligand:protein complex?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and D"},{"key":"3","text":"C and D"},{"key":"4","text":"A only"}],"answer":"1"},{"id":73,"part":"C","unit":1,"blocks":[{"t":"p","h":"The following are four biological processes that occur inside a living cell.<br>A. Spontaneous cis-trans isomerization of proline in proteins<br>B. Co-translational protein folding<br>C. α-helix formation<br>D. Hydrogen bond formation in free water<br>Which one of the following options represents the slowest to fastest order of the timescale for these processes?"}],"options":[{"key":"1","text":"D &gt; C &gt; B &gt; A"},{"key":"2","text":"A &gt; B &gt; C &gt; D"},{"key":"3","text":"D &gt; C &gt; A &gt; B"},{"key":"4","text":"C &gt; B &gt; D &gt; A"}],"answer":"2"},{"id":74,"part":"C","unit":1,"blocks":[{"t":"p","h":"A protein with a binding pocket containing amino acid residues, Asp (pKa = 4.0), and His (pKa = 6.5) interacts with a ligand at pH 7.0 at 25°C. The binding affinity of the ligand increases 10-fold upon ‘His’ protonation. Assuming ‘His’ protonation is the sole contributor to the enhanced binding, calculate the fraction of ‘His’ residue protonation and the change in the binding free energy corresponding to the enhanced affinity (R = 1.987 cal/mol/K)."}],"options":[{"key":"1","text":"0.48 and -3.61 kcal/mol"},{"key":"2","text":"0.76 and -2.46 kcal/mol"},{"key":"3","text":"0.96 and -1.63 kcal/mol"},{"key":"4","text":"0.24 and -1.36 kcal/mol"}],"answer":"4"},{"id":75,"part":"C","unit":1,"blocks":[{"t":"p","h":"A 20-bp GC-rich promoter undergoes a conformational transition between the B-form to Z-form of DNA, involving bases 6 to 13. The rest of the bases always remain in the B-form. The B- to Z- DNA transition occurs with a half-life of 2 s, and Z- to B-DNA transition has a half-life of 6 s. If the cognate transcription factor requires 10 continuous B-DNA base pairs for binding, for how many seconds in a 20 s window can the transcription factor remain bound to the promoter, assuming steady-state conditions?"}],"options":[{"key":"1","text":"4 s"},{"key":"2","text":"5 s"},{"key":"3","text":"10 s"},{"key":"4","text":"15 s"}],"answer":"2"},{"id":76,"part":"C","unit":1,"blocks":[{"t":"p","h":"The following graph represents the enzyme kinetics observed for an enzyme (E) in the presence of 2 different inhibitors, P and Q, each at two different concentrations (x-axis — 1/v; 1/(moles/min); y-axis 1/[S]; 1/μM)."},{"t":"img","src":"data:image/webp;base64,","w":287,"h":159,"alt":"Figure for question 76"},{"t":"p","h":"Based on the graph, what is the substrate concentration (in µM) at which both inhibitors achieve 50% inhibition?"}],"options":[{"key":"1","text":"0.333"},{"key":"2","text":"0.5"},{"key":"3","text":"1.0"},{"key":"4","text":"2.0"}],"answer":"3"},{"id":77,"part":"C","unit":9,"blocks":[{"t":"p","h":"Following statements were made regarding the theory of symbiogenesis in the origin of eukaryotic cells.<br>A. Mitochondria and chloroplasts have typically their own circular DNA, similar to bacterial DNA.<br>B. Mitochondria and chloroplasts are surrounded by a single membrane like other organelles.<br>C. Division of mitochondria and chloroplasts occurs synchronously with the division of nuclear genome.<br>D. Ribosomes in mitochondria and chloroplasts are similar to those found in prokaryotes.<br>E. Genetic analysis shows that mitochondrial DNA is closely related to certain proteobacteria.<br>Which one of the following options has all the correct statements?"}],"options":[{"key":"1","text":"A, B, C, D and E"},{"key":"2","text":"A, C and E only"},{"key":"3","text":"A, D and E only"},{"key":"4","text":"A, C, D and E only"}],"answer":"3"},{"id":78,"part":"C","unit":2,"blocks":[{"t":"p","h":"In eukaryotes, many cells can assemble a spindle in the absence of centrosomes as in the case of plant cells during mitosis, and animal cells during meiosis in females. In this context, centrosome-free mitotic extracts from frog oocytes, when supplied with beads covered with DNA, are sufficient to assemble the mitotic spindle. Listed below are a few proteins that could be involved in spindle assembly in such a setting:<br>A. Ran GTPase<br>B. Ran-GEF<br>C. TPX2<br>D. Myosin V<br>Which one of the following options has all proteins that are directly involved in controlling spindle assembly without centrosomes?"}],"options":[{"key":"1","text":"A only"},{"key":"2","text":"A and B only"},{"key":"3","text":"A, B, and C only"},{"key":"4","text":"A, B, C, and D"}],"answer":"3"},{"id":79,"part":"C","unit":2,"blocks":[{"t":"p","h":"Given below are a few statements about meiosis in animal cells:<br>A. Failure of the chiasma formation leads to non-disjunction in meiosis I.<br>B. Meiotic cohesin Rec8 ensures mono-orientation of sister chromatids in meiosis II.<br>C. Crossover interference reduces clustering of recombination sites.<br>D. Residual double-strand breaks arrest meiosis at metaphase.<br>Which one of the following options has all the correct statements?"}],"options":[{"key":"1","text":"A and B only"},{"key":"2","text":"A, C and D"},{"key":"3","text":"A, B and C"},{"key":"4","text":"B and C only"}],"answer":"2"},{"id":80,"part":"C","unit":2,"blocks":[{"t":"p","h":"Column X lists different types of ion channels and column Y defines the nature/property of these channels."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Channel rhodopsin","i. Voltage-gated"],["B. Shaker-related potassium channels","ii. Mechano-sensitive"],["C. Piezo ion channel","iii. Ligand-gated"],["D. Acetylcholine receptor","iv. Light driven"]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A(iii), B(i), C(iv), D(ii)"},{"key":"2","text":"A(i), B(ii), C(iv), D(iii)"},{"key":"3","text":"A(iv), B(iii), C(ii), D(i)"},{"key":"4","text":"A(iv), B(i), C(ii), D(iii)"}],"answer":"4"},{"id":81,"part":"C","unit":2,"blocks":[{"t":"p","h":"To test if viral proteins are transported between Golgi stacks in vesicles or are released into the cytosol by one Golgi stack and taken up by another, viral protein transport was examined between Golgi stacks of infected and uninfected cells. Which one of the following experimental designs would best distinguish these two hypotheses?"}],"options":[{"key":"1","text":"Test whether viral protein transport happens in the presence of antibodies depleting clathrin in acceptor Golgi stacks"},{"key":"2","text":"Test whether viral protein transport happens in the presence of antibodies depleting COPII in acceptor Golgi stacks"},{"key":"3","text":"Test whether viral protein transport happens in the presence of protease in the assay mix."},{"key":"4","text":"Test whether viral protein transport happens when either donor or acceptor Golgi stacks are treated with detergents sequentially"}],"answer":"3"},{"id":82,"part":"C","unit":14,"blocks":[{"t":"p","h":"Chromatin immunoprecipitation (ChIP) and RT-PCR were performed to investigate the activation of expression of a particular gene, results of which are shown below. X, Y and Z indicate ChIP with antibodies for specific proteins, and 'RNA' shows gene expression at the indicated time points."},{"t":"img","src":"data:image/webp;base64,","w":287,"h":151,"alt":"Figure for question 82"},{"t":"p","h":"Based on the results, choose the option that correctly identifies the X, Y and Z proteins."}],"options":[{"key":"1","text":"X: H4K8Ac; Y: TBP; Z: H3K9Ac"},{"key":"2","text":"X: TBP; Y: H4K8Ac; Z: H3K9Ac"},{"key":"3","text":"X: H4K8Ac; Y: H3K9Ac; Z: TBP"},{"key":"4","text":"X: H3K9Ac; Y: TBP; Z: H4K8Ac"}],"answer":"1"},{"id":83,"part":"C","unit":3,"blocks":[{"t":"p","h":"Circular genomic DNA isolated from actively replicating stages of organisms, P and Q were digested with a restriction enzyme that cuts both genomes only once. Electron- micrographs of the digested DNAs shown below"},{"t":"img","src":"data:image/webp;base64,","w":287,"h":124,"alt":"Figure for question 83"},{"t":"p","h":"The following comments are made on the number of replication origins and directionality of the replication fork(s):<br>A. In organism P there are two replication origins, and replication is bidirectional.<br>B. In organism P there is one replication origin, and replication is bidirectional.<br>C. In organism Q there is one replication origin, and replication is bidirectional.<br>D. In organism Q there is one replication origin, and replication is unidirectional.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"A and D"},{"key":"3","text":"B and C"},{"key":"4","text":"B and D"}],"answer":"3"},{"id":84,"part":"C","unit":13,"blocks":[{"t":"p","h":"The following constructs, A or B, have been introduced into two different cultures of eukaryotic cells:"},{"t":"img","src":"data:image/webp;base64,","w":287,"h":125,"alt":"Figure for question 84"},{"t":"p","h":"Cre recombinase can act upon loxP-loxP and loxN-loxN sites. The following outcomes have been predicted on the types of fluorescence emitted by the cells upon induction of Cre-recombinase:<br>A. The cells transfected with construct A will yield three types of cells: each type expressing either red or green or yellow fluorescence.<br>B. The cells transfected with construct B will yield three types of cells: each type expressing either red or green or yellow fluorescence.<br>C. The cells transfected with construct A will yield two types of cells: each type expressing either red or green fluorescence.<br>D. The cells transfected with construct B will yield two types of fluorescent cells: each type expressing either red or yellow fluorescence.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and D"},{"key":"2","text":"A and B"},{"key":"3","text":"B and C"},{"key":"4","text":"C and D"}],"answer":"1"},{"id":85,"part":"C","unit":5,"blocks":[{"t":"p","h":"ENZ function prevents premature differentiation of mouse neural stem cells. Kinase inhibitor treatment differentiates these cells prematurely. This is prevented if a specific serine-to- aspartate (S to D) mutation is introduced in ENZ. Based on this information, which one of the following statements is INCORRECT?"}],"options":[{"key":"1","text":"The specific serine to aspartate substitution has the same effect as phosphorylation of ENZ on neural stem cell differentiation."},{"key":"2","text":"The specific serine may be the site of ENZ phosphorylation."},{"key":"3","text":"The serine-to-aspartate mutation is expected to yield the same results as an asparagine substitution."},{"key":"4","text":"The serine-to-aspartate mutation is expected to yield the same results as a glutamic acid substitution."}],"answer":"3"},{"id":86,"part":"C","unit":3,"blocks":[{"t":"p","h":"A lambda bacteriophage integrated into the genome of E. coli and became lysogenic. Upon UV irradiation, it is expected that the lytic cycle will be induced. Due to mutations that have occurred as a result of UV irradiation, you find that the lambda bacteriophage remains in the lysogenic state and lysis is impaired. Mutations in the following genes have been proposed to explain this observation.<br>A. cI gene, protease cleavage site<br>B. cII gene, DNA binding site<br>C. RecA gene of E. coli<br>D. RuvA gene of E. coli<br>Which one of the following options represents all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and D"},{"key":"3","text":"A and C"},{"key":"4","text":"C and D"}],"answer":"3"},{"id":87,"part":"C","unit":3,"blocks":[{"t":"p","h":"A eukaryotic protein, 'X' activates a target gene by increasing its transcription when an inducer is added. The results of the experiments are shown below:"},{"t":"tbl","cls":"","rowHead":false,"head":[["Experiment","Results without inducer","Results with inducer"]],"rows":[["Immunofluorescence of protein 'X'","No colocalization with DAPI","Colocalization with DAPI"],["Electrophoretic Mobility Shift Assay (EMSA)","No binding to probe derived from the promoter of the target gene","No binding to probe derived from the promoter of the target gene"],["Chromatin immunoprecipitation of the promoter of the target gene","Low acetylation","High acetylation"]]},{"t":"p","h":"Which one of the following options is the correct mechanism of protein X-mediated transcriptional activation of the target gene upon addition of the inducer?"}],"options":[{"key":"1","text":"It acts in the cytoplasm as part of a signal transduction cascade."},{"key":"2","text":"It moves to the nucleus and acts as a coactivator."},{"key":"3","text":"It remains in the nucleus and acts as a chromatin modifier."},{"key":"4","text":"It moves to the cytoplasm and acts as a repressor."}],"answer":"2"},{"id":88,"part":"C","unit":3,"blocks":[{"t":"p","h":"In an in vitro translation reaction, the 43S pre-initiation complex (PIC) was incubated with the in vitro transcribed and capped mRNA for Gene X, followed by addition of the 60S subunit. As a control, mRNA for Gene Y isolated from cells was incubated in the same reaction. The mRNA for Gene Y was bound to the 80S ribosomes and polyribosomes, while mRNA of Gene X remained unbound. In a parallel experiment, mRNAs for both Gene X and Gene Y were found to be associated in vivo with 80S and polyribosomes. The following statements were made to explain the above observation:<br>A. The in vitro system was globally defective for 80S assembly.<br>B. Gene X mRNA has a sequence or structural feature that specifically prevents 80S assembly in vitro.<br>C. Gene X mRNA lacks a start codon.<br>D. Gene X mRNA requires other cellular factors which are absent in the in vitro mix to permit initiation.<br>E. The in vitro assay preferentially degrades Gene X mRNA.<br>Which one of the following options represents all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"B and D"},{"key":"4","text":"D and E"}],"answer":"3"},{"id":89,"part":"C","unit":4,"blocks":[{"t":"p","h":"The following statements were made about host-pathogen interactions during influenza virus infection:<br>A. Entry of the virus is mediated by the interaction of the HA-protein of the virus with sialic acid receptors on the airway epithelium.<br>B. CTLs are primed in the thymus to kill respiratory epithelial cells that present viral antigens on MHC-I molecules.<br>C. CTLs are primed in the thymus to kill respiratory epithelial cells that present viral antigens on MHC-II molecules.<br>D. Viral neuraminidase is required for the release of mature viruses from infected cells.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"A, B and D"},{"key":"3","text":"B and D only"},{"key":"4","text":"A and D only"}],"answer":"4"},{"id":90,"part":"C","unit":4,"blocks":[{"t":"p","h":"Signalling pathways that are important for tumorigenesis and cancer include those involved in cell proliferation and cell growth. The following statements were made regarding pathways and molecules involved in cancer:<br>A. Abnormal activation of the PI3-kinase/Akt pathway is involved in dysregulated growth.<br>B. Bcl2 overexpression and enhanced apoptosis lead to efficient clearance of damaged cancer cells.<br>C. Loss of p53 can allow cells with damaged DNA to escape apoptosis and continue to proliferate.<br>D. Inhibition of the Rho family GTPase RhoC leads to enhanced actin-based cell motility and facilitates metastasis.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"A and C"},{"key":"3","text":"B and C"},{"key":"4","text":"C and D"}],"answer":"2"},{"id":91,"part":"C","unit":4,"blocks":[{"t":"p","h":"The following statements were made about major histocompatibility complex (MHC) molecules:<br>A. Multiple MHC-I molecules can be expressed on a single cell.<br>B. MHC-I molecules exhibit greater diversity than antibodies.<br>C. MHC-I haplotypes inherited from the mother and father and expressed on a given cell are codominant.<br>D. All MHC-I molecules on a given cell express the same endogenous peptide.<br>E. MHC-I molecules are present on platelets.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"A, C and E"},{"key":"3","text":"B and D"},{"key":"4","text":"C, D and E"}],"answer":"2"},{"id":92,"part":"C","unit":3,"blocks":[{"t":"p","h":"During development, yfg expression is regulated by proteins E, F and G, which are abundant and have long half-lives. After a \"specific stage of development\", the protein E is activated by a single short wave of phosphorylation. This leads to the following events: • Phosphorylated E activates F. • Active F activates G. • Active G promotes yfg expression. • Active F completely inhibits E, and active G completely inhibits F function. Which one of the following describes the expression of yfg soon after the \"specific stage of development\" is reached?"}],"options":[{"key":"1","text":"Continuously transcribing"},{"key":"2","text":"One pulse of transcription"},{"key":"3","text":"Transcription not initiated"},{"key":"4","text":"Multiple pulses of transcription"}],"answer":"2"},{"id":93,"part":"C","unit":6,"blocks":[{"t":"p","h":"The following statements are made with respect to signal transduction events in phytohormone signalling in plants:<br>A. Autophosphorylation of a histidine residue in the receiver domain of the response regulator is important for signal transduction through the two-component system.<br>B. Phosphorylation of a conserved aspartate residue in the transmitter domain of the histidine kinase is important for the two-component system.<br>C. CYTOKININ RESPONSE 1 (CRE1), a cytokinin receptor, functions as an Arabidopsis histidine- containing phosphotransfer (AHP) factor.<br>D. In Arabidopsis, pseudo-AHP, called AHP6, acts as an inhibitor of cytokinin signalling.<br>E. ETR1, an ethylene receptor in Arabidopsis, has histidine kinase activity and a receiver domain. Which one of the following options is a combination of all correct statements?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"B and D"},{"key":"3","text":"C and E"},{"key":"4","text":"D and E"}],"answer":"4"},{"id":94,"part":"C","unit":6,"blocks":[{"t":"p","h":"The following statements are made regarding the functioning of phytochromes A and B during light signaling in plants:<br>A. Phytochrome B (PhyB) lacks nuclear localization signal (NLS) and after perceiving light, it takes hours for nuclear import.<br>B. Phytochrome A (PhyA) contains NLS and its nuclear import occurs rapidly.<br>C. PFR form of PhyA depends on FAR-RED ELONGATED HYPOCOTYL 1 (FHY1) and its homolog FHL for nuclear import.<br>D. PFR form of PhyB depends on FHY1 and its homolog FHL for nuclear import.<br>Which one of the following options represents all correct statement(s)?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"C only"},{"key":"3","text":"A and C"},{"key":"4","text":"D only"}],"answer":"2"},{"id":95,"part":"C","unit":5,"blocks":[{"t":"p","h":"The following statements were made regarding cell fate specification of trophoblast and inner cell mass (ICM) during mammalian embryogenesis:<br>A. Oct4 represses Cdx2 expression, enabling some cells to become ICM.<br>B. Cdx2 synthesized by the trophoblast cells activate Oct4 and Nanog.<br>C. Expression of Nanog allows cells of the ICM to retain their pluripotency.<br>D. YAP binds to TEAD4 and represses Cdx2 in the trophoblast cells.<br>Which one of the following options correctly represent events that determine the fate of trophoblasts and ICM?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and C"}],"answer":"4"},{"id":96,"part":"C","unit":5,"blocks":[{"t":"p","h":"In amphibians and fish, the cells of the organizer ultimately contribute to -(i) pharyngeal endoderm, (ii) head mesoderm, (iii) dorsal mesoderm, and (iv) dorsal blastopore lip. The following statements are made about the function of the organizer and its derivatives:<br>A. The pharyngeal endoderm and pre-chordal plate prevent formation of forebrain and midbrain.<br>B. The organizer has the ability to dorsalize the ectoderm and induce formation of the neural tube.<br>C. The dorsal mesoderm inhibits induction of the hindbrain and trunk.<br>D. The organizer tissue possesses the ability to dorsalize the surrounding mesoderm into somite- forming mesoderm.<br>Which one of the following options is a combination of all correct statements?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"B and D only"},{"key":"3","text":"A, B and D"},{"key":"4","text":"B, C and D"}],"answer":"2"},{"id":97,"part":"C","unit":14,"blocks":[{"t":"p","h":"Immunoprecipitation (IP) of protein X from cell lysate using anti-X antibody, followed by RT-PCR for mRNA-Y, indicates the presence of protein X-mRNA-Y complex in vivo. To confirm this interaction, recombinant protein X and in vitro transcribed mRNA-Y are incubated, followed by affinity purification of protein X. However, mRNA-Y was not present in the eluates containing X but rather in the unbound fraction. Given below are a few statements to explain the observations.<br>A. Protein X and mRNA-Y are expressed at the same level in the cell, so the interaction is robust.<br>B. Protein X and mRNA-Y physically interact via a bridge protein/co-factor absent in the purified protein X.<br>C. mRNA-Y binds to the antibody used in the immunoprecipitation.<br>D. The mRNA binding domain of the recombinant protein X may have an altered conformation.<br>Which one of the following is a combination of all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and D"},{"key":"3","text":"C only"},{"key":"4","text":"C and D"}],"answer":"2"},{"id":98,"part":"C","unit":5,"blocks":[{"t":"p","h":"Experiments addressing axes patterning in amphibian embryos are listed in column X and the observations are listed in column Y."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Grafting of dorsal blastopore lip from donor early gastrula into presumptive ventral epidermis of host early gastrula","i. Rescue of dorsal development"],["B. Injection of noggin mRNA into UV-treated Xenopus embryos","ii. Induction of secondary head structures"],["C. Injection of morpholinos to inhibit BMPs 2, 4, and 7","iii. Formation of a secondary embryo"],["D. Grafting of anterior archenteron roof from late gastrula into the blastocoel of early gastrula","iv. Enlarged neural tube"]]},{"t":"p","h":"Which one of the following options represents the correct match between Column X and Column Y?"}],"options":[{"key":"1","text":"A - iii, B - i, C - iv, D - ii"},{"key":"2","text":"A - ii, B - iii, C - iv, D - i"},{"key":"3","text":"A - iv, B - i, C - ii, D - iii"},{"key":"4","text":"A - iii, B - ii, C - iv, D - i"}],"answer":"1"},{"id":99,"part":"C","unit":5,"blocks":[{"t":"p","h":"Given below are the different stages of Arabidopsis embryogenesis (Column X) and their characteristic patterns of cell division (Column Y)."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Zygotic","(i) Formation of an 8-cell embryo, exhibiting radial symmetry and undergoing additional cell division to create the protoderm"],["B. Globular","(ii) Polarized growth of cells followed by a symmetric transverse division giving rise to a small apical cell and an elongated basal cell"],["C. Heart","(iii) Cell elongation and cellular differentiation processes throughout the embryonic axis with visible distinction between the adaxial and abaxial tissue of the cotyledons"],["D. Torpedo","(iv) Focused cell division forming two cotyledons, giving bilateral symmetry to the embryo"]]},{"t":"p","h":"Which one of the following options represents the correct match between Column X and Column Y?"}],"options":[{"key":"1","text":"A (i); B (ii); C (iii); D (iv)"},{"key":"2","text":"A (ii); B (i); C (iv); D (iii)"},{"key":"3","text":"A (ii); B (i); C (iii); D (iv)"},{"key":"4","text":"A (i); B (iv); C (ii); D (iii)"}],"answer":"2"},{"id":100,"part":"C","unit":5,"blocks":[{"t":"p","h":"Following statements are made regarding sex determination in plants:<br>A. In Silene latifolia, females are homogametic (XX) and males are heterogametic (XY).<br>B. Papaya (Carica papaya) shows trioecy, but its sex determination is not associated with sex chromosomes.<br>C. All dioecious plants with separate sexes possess heteromorphic sex chromosomes.<br>D. Plant sex chromosomes are ancient, and their Y chromosomes are highly degenerated, much like those in mammals.<br>E. Unlike animals, dosage compensation is generally weak or absent in plant sex chromosome systems.<br>Which one of the following combinations contains all INCORRECT statements?"}],"options":[{"key":"1","text":"A, C and E"},{"key":"2","text":"B, C and D"},{"key":"3","text":"A and D"},{"key":"4","text":"B and E"}],"answer":"2"},{"id":101,"part":"C","unit":6,"blocks":[{"t":"p","h":"The following statements are made regarding photosynthesis in a mutant maize (C4 plant) that lacks functional bundle sheath chloroplasts:<br>A. Photorespiration would remain low due to PEP carboxylase activity.<br>B. Calvin cycle would be severely compromised, reducing sugar production.<br>C. Carbon fixation would shift entirely to mesophyll cells without yield penalty.<br>D. CO₂ concentration around Rubisco would increase dramatically.<br>Which one of the following options is a combination of all INCORRECT statements?"}],"options":[{"key":"1","text":"A and B only"},{"key":"2","text":"A, B and C"},{"key":"3","text":"C and D only"},{"key":"4","text":"A, C and D"}],"answer":"4"},{"id":102,"part":"C","unit":6,"blocks":[{"t":"p","h":"Beyond its primary role in reducing atmospheric nitrogen to ammonia during symbiotic nitrogen fixation, the nitrogenase enzyme complex is also capable of catalyzing other reactions. Listed below are some reactions:<br>A. Acetylene reduction (C₂H₂ → C₂H₄)<br>B. H₂ production (2H⁺ → H₂)<br>C. ATP hydrolysis (ATP → ADP + Pi)<br>D. Oxidized ferredoxin to Reduced Ferredoxin<br>E. NAD reduction (NAD⁺ + H⁺ → NADH)<br>Which one of the following options represents the combination of reactions that are NOT catalysed by the nitrogenase enzyme complex?"}],"options":[{"key":"1","text":"B and C"},{"key":"2","text":"D and E"},{"key":"3","text":"A and C"},{"key":"4","text":"B and D"}],"answer":"2"},{"id":103,"part":"C","unit":6,"blocks":[{"t":"p","h":"Following statements are made regarding abscisic acid (ABA) signalling during water stress in plants:<br>A. ABA causes membrane depolarization by decreasing cytosolic calcium levels.<br>B. ABA causes alkalinisation of the cytosol which stimulates opening of K⁺ efflux channels.<br>C. ABA inhibits the activity of the plasma membrane H⁺-ATPase which results in membrane depolarization.<br>D. During stomatal closure, ABA induces reorganization of tubulin cytoskeleton mediated by Rho GTPases.<br>E. ABA induced membrane depolarization occur by release of calcium from endoplasmic reticulum and vacuoles.<br>Which one of the following options is a combination of all correct statements?"}],"options":[{"key":"1","text":"A, B, D and E"},{"key":"2","text":"B, C and E"},{"key":"3","text":"A, B, C and D"},{"key":"4","text":"C, D and E"}],"answer":"2"},{"id":104,"part":"C","unit":6,"blocks":[{"t":"p","h":"Given below are a few statements regarding Aquaporin-mediated water transport in plants:<br>A. The activity of aquaporins is regulated by altered pH and Ca²⁺ concentration as well as phosphorylation.<br>B. Aquaporin activity is also regulated by reactive oxygen species.<br>C. Aquaporins are restricted only to epidermis and endodermal cells and not present in xylem parenchyma.<br>D. Aquaporins do not mediate influx of boric acid and salicylic acid into cytosol.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"1"},{"id":105,"part":"C","unit":6,"blocks":[{"t":"p","h":"The following statements are made regarding phenolic biosynthesis in plants.<br>A. The lignans and flavonoids have abundant methylated carboxyl groups, compared to methylated hydroxyl groups.<br>B. Cells producing lignans and flavonoids have a very high demand for S- adenosylmethionine.<br>C. The majority of methylation reactions involved in the formation of phenolics are catalyzed by O-methyltransferases.<br>D. The catechol-O-methyltransferase (COMT) has strict substrate specificity.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"2"},{"id":106,"part":"C","unit":6,"blocks":[{"t":"p","h":"The following statements are made with respect to the major classes of heat shock proteins (HSP) in plants.<br>A. Cytosolic HSP100 is essential while the chloroplast HSP100 / Clpβ family protein is not essential for heat stress response.<br>B. Proteins of HSP90 family are exclusively localized in the nucleus.<br>C. Members of HSP60 protein family, chaperonins, are abundant even at normal temperatures.<br>D. The C-terminal domain of small HSPs is homologous to α-crystallins, proteins found in vertebrate eye lens.<br>Which one of the following options is a combination of all correct statements?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"B and D"},{"key":"3","text":"A and B"},{"key":"4","text":"C and D"}],"answer":"4"},{"id":107,"part":"C","unit":4,"blocks":[{"t":"p","h":"The following statements propose some of the similarities and differences between classic non- peptide neurotransmitters (CNN) and peptide neurotransmitters (PN):<br>A. CNN are synthesized at the presynaptic terminal while PN are synthesized in the cell body.<br>B. PN receptors are confined to the specific synapse at which PN is released like that of CNN.<br>C. When one neuron (containing both CNN and PN) is stimulated at low frequency, both PN and CNN are released from the presynaptic terminal, but at higher frequencies, only CNN is released.<br>D. The typical action of CNN has short latency and short duration (milliseconds) while PN action may have long latency and may persist for long duration (seconds).<br>Which one of the following options represents a combination of all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"4"},{"id":108,"part":"C","unit":7,"blocks":[{"t":"p","h":"The physiological regulation of plasma osmolality by osmotically active neurons (osmoreceptors) in the organum vasculosum of lamina terminalis (OVLT) of hypothalamus is described in the following statements:<br>A. In hyperosmolal state, the non-selective cationic channels in the osmoreceptor membrane becomes active causing hyperpolarization of receptor cells.<br>B. In hyperosmolal state, shrinkage of osmoreceptor cells occurs.<br>C. Activated osmoreceptors send action potentials to the supraoptic nucleus (SON) and paraventricular nucleus (PVN) to release arginine vasopressin (AVP).<br>D. In hypoosmolal state, the stretching of osmoreceptor membrane causes inactivation of transient receptor vanilloid protein 4 (TRVP4) resulting in the activation of osmoreceptors.<br>Which one of the following options represents a combination of all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"2"},{"id":109,"part":"C","unit":7,"blocks":[{"t":"p","h":"The following statements are put forth about hormonal changes during normal pregnancy in humans:<br>A. Pituitary secretion of FSH and LH increases.<br>B. Aldosterone secretion increases.<br>C. Glucocorticoid secretion decreases.<br>D. Thyroxine secretion increases.<br>Which one of the following options has a combination of all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"C and D"},{"key":"3","text":"A and C"},{"key":"4","text":"B and D"}],"answer":"4"},{"id":110,"part":"C","unit":7,"blocks":[{"t":"p","h":"Given below are statements about ion transport proteins in pancreatic duct cells which influence the composition of pancreatic juice:<br>A. Primary Cl⁻/HCO₃⁻ exchanger is located on the luminal side.<br>B. CFTR is located primarily on the basolateral side.<br>C. Na⁺-bicarbonate cotransporter is located on the basolateral side.<br>D. Na⁺/hydrogen exchanger-1 is located on the luminal side.<br>Which one of the following options has a combination of all correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"C and D"},{"key":"3","text":"A and C"},{"key":"4","text":"B and D"}],"answer":"3"},{"id":111,"part":"C","unit":7,"blocks":[{"t":"p","h":"Given below are few hormones (Column X) and their specific inhibitors (Column Y)."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Growth hormone","i. Mifepristone"],["B. Progestogens","ii. Inhibin B"],["C. Parathormone","iii. Somatostatin"],["D. Follicle-stimulating hormone","iv. High calcium levels"]]},{"t":"p","h":"Which one of the following combinations correctly matches the hormones with their inhibitors?"}],"options":[{"key":"1","text":"A – i; B – ii; C – iv; D – iii"},{"key":"2","text":"A – iii; B – i; C – iv; D – ii"},{"key":"3","text":"A – iv; B – ii; C – iii; D – i"},{"key":"4","text":"A – iii; B – iv; C – i; D – ii"}],"answer":"2"},{"id":112,"part":"C","unit":7,"blocks":[{"t":"p","h":"The following statements are made about body temperature regulation in humans:<br>A. Lactic acid and potassium ions are less concentrated in sweat while sweating little than while sweating a lot.<br>B. When the temperature of the surroundings becomes greater than that of the skin, body loses heat by conduction.<br>C. When heat is applied directly to the pre-optic area of hypothalamus by inserting a thermode in the brain, the animal begins to sweat profusely.<br>D. Chemical thermogenesis through thyroid gland stimulation requires weeks of exposure to cold temperature.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"C and D"},{"key":"2","text":"B and C"},{"key":"3","text":"A and B"},{"key":"4","text":"A and D"}],"answer":"1"},{"id":113,"part":"C","unit":8,"blocks":[{"t":"p","h":"Recombination between two genes in Neurospora crassa yielded equal numbers of parental ditype (PD) and tetratype (TT), and 12 times as many TT as non-parental ditype (NPD). What is the distance between the genes in map units (mu)?"}],"options":[{"key":"1","text":"6 mu"},{"key":"2","text":"7 mu"},{"key":"3","text":"14 mu"},{"key":"4","text":"28 mu"}],"answer":"4"},{"id":114,"part":"C","unit":8,"blocks":[{"t":"p","h":"In a plant heterozygous for a reciprocal translocation involving chromosome P (ABCDEFGH) and chromosome Q (123456), meiosis I produces a quadrivalent as shown in the figure, which after meiosis II results in gametes of types labelled X, Y and Z."},{"t":"img","src":"data:image/webp;base64,","w":380,"h":128,"alt":"Figure for question 114"},{"t":"p","h":"Which one of the following combinations correctly represents the segregation pattern of gametes that arise from the quadrivalent configuration as shown in the diagram?"}],"options":[{"key":"1","text":"X = Alternate Y = Adjacent II Z = Adjacent I"},{"key":"2","text":"X = Adjacent II Y = Alternate Z = Adjacent I"},{"key":"3","text":"X = Adjacent I Y = Adjacent II Z = Alternate"},{"key":"4","text":"X = Adjacent I Y = Alternate Z = Adjacent II"}],"answer":"4"},{"id":115,"part":"C","unit":8,"blocks":[{"t":"p","h":"Given below are a few statements related to inheritance biology:<br>A. A crossover is the breakage of two DNA molecules at the same position and their rejoining in two reciprocal recombinant combinations.<br>B. Crossing over takes place at the four-chromatid stage.<br>C. As the distance between two genes increases, the recombination frequencies move closer to 50%.<br>D. Percentage of recombinants between two genes can be used as a quantitative index of the accurate physical distance between them.<br>Which one of the following options is a combination of all correct statements?"}],"options":[{"key":"1","text":"A and C only"},{"key":"2","text":"B and D only"},{"key":"3","text":"A, B and C"},{"key":"4","text":"B, C and D"}],"answer":"3"},{"id":116,"part":"C","unit":8,"blocks":[{"t":"p","h":"In T4 phage, a mutation in the rII locus gives rise to large and round plaques. The wild type plaques are small and ragged. Ten independent mutants (M1 to M10) in the rII locus were isolated. In order to test whether the mutations affected the same protein coding regions, E. coli cells were infected with two mutant phages at a time. The plaques obtained from such infection were either small and ragged (+) or large and round (-). The results obtained from all combinations of infection involving the ten mutants is summarized below:"},{"t":"tbl","cls":"matrix","rowHead":true,"head":[["","M1","M2","M3","M4","M5","M6","M7","M8","M9","M10"]],"rows":[["M1","−","+","−","−","+","+","+","+","+","−"],["M2","","−","+","+","−","−","−","−","−","+"],["M3","","","−","−","+","+","+","+","+","−"],["M4","","","","−","+","+","+","+","+","−"],["M5","","","","","−","−","−","−","−","+"],["M6","","","","","","−","−","−","−","+"],["M7","","","","","","","−","−","−","+"],["M8","","","","","","","","−","−","+"],["M9","","","","","","","","","−","+"],["M10","","","","","","","","","","−"]]},{"t":"p","h":"The following conclusions were drawn from the above observations:<br>A. The mutants map to two complementation groups.<br>B. M1 and M10 are mutations in two different genes.<br>C. Each complementation group is represented by 5 mutants.<br>Which one of the following options represents a combination of correct statement(s)?"}],"options":[{"key":"1","text":"A only"},{"key":"2","text":"B only"},{"key":"3","text":"A and B"},{"key":"4","text":"B and C"}],"answer":"1"},{"id":117,"part":"C","unit":13,"blocks":[{"t":"p","h":"Given below are different types of mapping populations in plants (Column X) and their characteristic features (Column Y):"},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. F₂ mapping population","i. 1:0 segregation ratio of dominant markers"],["B. Backcross population","ii. 1:1 segregation ratio for both dominant and codominant markers"],["C. RILS","iii. Recombination is represented only from the male source"],["D. F₁DH","iv. 3:1 phenotypic segregation ratio of dominant markers"]]},{"t":"p","h":"Which one of the following options is the correct match between all terms of Column X and Column Y?"}],"options":[{"key":"1","text":"A-iv, B-i, C-ii, D-iii"},{"key":"2","text":"A-ii, B-iii, C-i, D-iv"},{"key":"3","text":"A-i, B-ii, C-iv, D-iii"},{"key":"4","text":"A-iii, B-iv, C-ii, D-i"}],"answer":"1"},{"id":118,"part":"C","unit":8,"blocks":[{"t":"p","h":"Conjugation experiments were performed by mixing four different auxotrophic strains (P, Q, R and S) of E. coli in different combinations. The generation of prototrophs in each of these combinations on appropriate minimal selection media is given below:"},{"t":"tbl","cls":"","rowHead":false,"head":[["Combination of strains","No. of prototrophs obtained"]],"rows":[["P and Q","20"],["S and R","1000"],["P and R","0"],["P and S","1000"]]},{"t":"p","h":"Based on the above data, the following statements were made:<br>A. Strains P and R are F⁻ strains.<br>B. Strain Q is a F⁺ strain.<br>C. Strain S is a Hfr strain.<br>D. Strains P and R are F⁺ and F⁻ strains, respectively.<br>E. Strains P and R are both Hfr strains.<br>Which one of the following options represents a combination of all correct statements?"}],"options":[{"key":"1","text":"A, C and D"},{"key":"2","text":"A, B and D"},{"key":"3","text":"B, C and E"},{"key":"4","text":"A, B and C"}],"answer":"4"},{"id":119,"part":"C","unit":9,"blocks":[{"t":"p","h":"Antibiotic resistant strains of various pathogenic bacteria are a serious concern for human health. The following table has the names of important bacteria (Column X), specific strains of which can cause serious illnesses (Column Y)."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Specific strains of Enterobacteriaceae","i. Re-emerged as a significant community- and hospital-acquired infection due to Methicillin resistance"],["B. Specific strains of Rickettsia","ii. Multidrug-resistant (MDR) strains found in humans and food, suggesting a potential for broader spread"],["C. Salmonella and Klebsiella pneumoniae","iii. A type of bacteria that is difficult to treat due to resistance to multiple antibiotics, mainly Carbapenem"],["D. Staphylococcus aureus","iv. The causative agent of murine typhus, which has shown transmission via organ transplants."]]},{"t":"p","h":"Which one of the options below is the correct match between all terms of Column X and Column Y?"}],"options":[{"key":"1","text":"A (iv) B (ii) C (iii) D (i)"},{"key":"2","text":"A (ii) B (i) C (iv) D (iii)"},{"key":"3","text":"A (iii) B (iv) C (ii) D (i)"},{"key":"4","text":"A (i) B (iii) C (iv) D (ii)"}],"answer":"3"},{"id":120,"part":"C","unit":10,"blocks":[{"t":"p","h":"Given below are names of plants (Column X) and the habitats (Column Y) in which they naturally occur:"},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Myristica fatua","i. Eastern Himalayas"],["B. Strobilanthes kunthiana","ii. Nilgiris"],["C. Madhuca indica","iii. Fresh water swamp forests"],["D. Rhododendron pendulum","iv. Central India"]]},{"t":"p","h":"Which one of the following options is a correct match of all terms between Column X and Column Y?"}],"options":[{"key":"1","text":"A-ii; B-i; C-iii; D-iv"},{"key":"2","text":"A-iv; B-iii; C-ii; D-i"},{"key":"3","text":"A-iii; B-ii; C-iv; D-i"},{"key":"4","text":"A-iii; B-iv; C-i; D-ii"}],"answer":"3"},{"id":121,"part":"C","unit":9,"blocks":[{"t":"p","h":"The table below lists taxonomic groups (Column X) and their morphological features (Column Y):"},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Crustacea","i. Two pairs of antennae"],["B. Chelicerata","ii. Antennae absent"],["C. Phoronida","iii. Presence of lophophore"]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A-ii, B-iii, C-i"},{"key":"2","text":"A-iii, B-i, C-ii"},{"key":"3","text":"A-i, B-iii, C-ii"},{"key":"4","text":"A-i, B-ii, C-iii"}],"answer":"4"},{"id":122,"part":"C","unit":9,"blocks":[{"t":"p","h":"A newly discovered small mammal from Madagascar lays eggs, has a cloaca, and shows electroreception through its snout. Molecular phylogenetics places it basal to all other living mammals. Based on these characters, which one of the following groups can it be assigned to?"}],"options":[{"key":"1","text":"Eutheria (placental mammals)"},{"key":"2","text":"Metatheria (marsupials)"},{"key":"3","text":"Prototheria (monotremes)"},{"key":"4","text":"Theria (marsupials + placentals)"}],"answer":"3"},{"id":123,"part":"C","unit":9,"blocks":[{"t":"p","h":"Given below are mechanisms that can facilitate major evolutionary transitions, such as the transition from genes to genomes, from unicellular to multicellular organisms, or from individuals to colonies.<br>A. Conflict mediation mechanisms maintain cooperation within emergent units.<br>B. Reduced genetic relatedness among cooperating units accelerates these transitions.<br>C. Division of labour evolves when specialisation increases group-level fitness more than individual fitness losses.<br>D. Transitions are irreversible once higher-level individuality is achieved.<br>Which one of the following options is a combination of all correct statements?"}],"options":[{"key":"1","text":"B and C"},{"key":"2","text":"A, C, and D"},{"key":"3","text":"A and C only"},{"key":"4","text":"C and D only"}],"answer":"3"},{"id":124,"part":"C","unit":9,"blocks":[{"t":"p","h":"Rhododendron arboreum of the family Ericaceae represents one of the ancient tree species of the genus showing extreme disjunction in the Indian subcontinent. It is represented by two sub- species viz., ssp. arboreum Smith in the forests of north-eastern India (temperate) and spp. nilagiricum distributed in the southern Western Ghats (tropical) of India with no distribution in the intervening plains. The following are some of the biogeographical theories that explain distribution of flora and fauna in the Indian subcontinent:<br>A. Island biogeography theory - The mountains function as isolated islands, promoting speciation.<br>B. Satpura Hypothesis - Species migrated between the Himalayas and the Western Ghats along a cooler, wetter corridor formed by the Satpura mountain range during periods of glacial expansion.<br>C. The Noah's Ark hypothesis/ 'Out of India' hypothesis - the Indian subcontinent is a remnant of the ancient supercontinent Gondwana, that acted as an isolated \"ark\" for millions of years, giving rise to some modern plant and mammalian groups.<br>Which one of the combinations of biogeographical models explain the distribution of R. arboreum?"}],"options":[{"key":"1","text":"A and C only"},{"key":"2","text":"A, B and C"},{"key":"3","text":"A and B only"},{"key":"4","text":"B and C only"}],"answer":"3"},{"id":125,"part":"C","unit":10,"blocks":[{"t":"p","h":"The taxon cycle is the predicted, progressive ecological and evolutionary changes in the descendants of founding populations. Taking the case of insular biotas, the figure below can be used to conceptualize and predict species types (a, b, c, d, e, f, g, h) in insular biotas based on fundamental capacities to evolve, immigrate and persist."},{"t":"img","src":"data:image/webp;base64,","w":228,"h":191,"alt":"Figure for question 125"},{"t":"p","h":"The table below has species types (Column X) and the possible traits (Column Y) associated with each type."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["P. c","i. Ecologically naïve species, and endemics near the end of the taxon cycle (e.g., dwarfed elephants)"],["Q. d","ii. An unlikely type, because the ability to evolve on isolated islands requires relatively long persistence"],["R. e","iii. Limited dispersal abilities; unlikely to inhabit isolated oceanic islands"],["S. b","iv. Supertramps, powerful dispersers such as microsnails, ferns, and rafting rodents"]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"P (i) Q (ii) R (iii) S (iv)"},{"key":"2","text":"P (iv) Q (i) R (ii) S (iii)"},{"key":"3","text":"P (ii) Q (iii) R (iv) S (i)"},{"key":"4","text":"P (iii) Q (iv) R (i) S (ii)"}],"answer":"4"},{"id":126,"part":"C","unit":10,"blocks":[{"t":"p","h":"The figure below shows a life cycle graph and the corresponding population projection matrix that is invariant over time for a population with four successive classes (1- 4). All contributions to class 1 from other classes is via fecundity."},{"t":"img","src":"data:image/webp;base64,","w":366,"h":135,"alt":"Figure for question 126"},{"t":"p","h":"Given this life cycle, no resource limitation, and initial numbers of individuals n₁ = 95, n₂ = 5, n₃ = 15, and n₄ = 4 in the four classes, consider the following statements regarding the future population states in a long-term simulation of population growth:<br>A. The population will grow and attain a stable class distribution.<br>B. The population will grow but the number of individuals in each class will be proportional to the initial numbers.<br>C. The population will grow but numbers of individuals in the classes will fluctuate disproportionately over time.<br>D. The population will grow at a fixed growth rate and all classes will grow at the same rates.<br>Which one of the following options represents a combination of all correct outcomes?"}],"options":[{"key":"1","text":"A and D"},{"key":"2","text":"A and C"},{"key":"3","text":"B and D"},{"key":"4","text":"B and C"}],"answer":"1"},{"id":127,"part":"C","unit":10,"blocks":[{"t":"p","h":"Nitrogen cycling is a critical ecosystem process. The table below lists the names of the processes (Column X) and nature of the reactions (Column Y) in the nitrogen cycle."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Ammonification","i. Conversion of N₂ to NH₃"],["B. Nitrogen fixation","ii. Hydrolysis of protein and oxidation of amino acids"],["C. Nitrification","iii. Reduction of NO₃⁻ to N₂O and N₂"],["D. Denitrification","iv. Oxidation of NH₃ to NO₂⁻ and from NO₂⁻ to NO₃⁻"]]},{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A (i); B (ii); C (iv); D (iii)"},{"key":"2","text":"A (ii); B (i); C (iv); D (iii)"},{"key":"3","text":"A (iv); B (i); C (iii); D (ii)"},{"key":"4","text":"A (ii); B (iv); C (iii); D (i)"}],"answer":"2"},{"id":128,"part":"C","unit":10,"blocks":[{"t":"p","h":"The table below gives life history characteristics of an endangered grassland bird in two geographically distinct populations. Assume that the species follows a logistic growth model, calculate the population growth rate (dN/dt) for both populations."},{"t":"tbl","cls":"","rowHead":false,"head":[["Population","No. of individuals (N)","births/year (B)","deaths/year (D)","Carrying capacity (K)"]],"rows":[["Rajasthan (R)","120","42","6","240"],["Maharashtra (M)","300","96","6","375"]]},{"t":"p","h":"Based on this data, which one of the following options gives the combination of correct inferences that can be drawn about the growth rate in both populations?"}],"options":[{"key":"1","text":"Both populations are growing AND (<i>dN</i>/<i>dt</i>)<sub><i>M</i></sub> &gt; (<i>dN</i>/<i>dt</i>)<sub><i>R</i></sub>"},{"key":"2","text":"Both populations are declining AND (<i>dN</i>/<i>dt</i>)<sub><i>M</i></sub> &lt; (<i>dN</i>/<i>dt</i>)<sub><i>R</i></sub>"},{"key":"3","text":"Both populations are growing AND (<i>dN</i>/<i>dt</i>)<sub><i>R</i></sub> = (<i>dN</i>/<i>dt</i>)<sub><i>M</i></sub>"},{"key":"4","text":"Both populations are declining AND (<i>dN</i>/<i>dt</i>)<sub><i>M</i></sub> &gt; (<i>dN</i>/<i>dt</i>)<sub><i>R</i></sub>"}],"answer":"3"},{"id":129,"part":"C","unit":10,"blocks":[{"t":"p","h":"In a systematic ecological survey of lepidopterans in a moist deciduous forest, a total of 197 species were recorded with 6814 individuals. The relative abundance data are presented below."},{"t":"img","src":"data:image/webp;base64,","w":287,"h":135,"alt":"Figure for question 129"},{"t":"p","h":"Keeping the above pattern in mind, which one of the statements below is correct?"}],"options":[{"key":"1","text":"Most species are common and are represented by a large number of individuals."},{"key":"2","text":"Most species are rare and few species are common, represented by a large number of individuals."},{"key":"3","text":"Most species are common and few species are rare, represented by few individuals."},{"key":"4","text":"Common and rare species are evenly present, with an equal representation of individuals."}],"answer":"2"},{"id":130,"part":"C","unit":10,"blocks":[{"t":"p","h":"Most vascular plants face two broad challenges that affect their growth, reproduction and evolutionary success. One major challenge (Stress) includes shortages of resources such as light, water, nutrients or other physicochemical limitations. A second major challenge (Disturbance) includes factors such as grazing, diseases, storms, frost, erosion, and fire. When cross tabulated, we get the following table:"},{"t":"tbl","cls":"","rowHead":true,"head":[["Intensity of Disturbance",["Intensity of Stress",2]],["","Low","High"]],"rows":[["Low","I","III"],["High","II","IV"]]},{"t":"p","h":"The outcome of this cross tabulation can be seen as fundamental life history strategies. Based on the above information, which one of the following statements is correct?"}],"options":[{"key":"1","text":"Conditions of low stress and low disturbance, result in a strategy that aims to maximize competitiveness and results in plants with small biomass, rapid reproduction and are short-lived."},{"key":"2","text":"Conditions of high stress and low disturbance result in plants that are slow growing, attaining low- to medium-biomass, with low reproductive output and are long-lived."},{"key":"3","text":"Conditions of low stress and high disturbance results in plants that are robust in terms of biomass, with low growth rates and slow reproduction."},{"key":"4","text":"Conditions of high stress and high disturbance results in small plants that can rapidly grow, have high reproductive output and are long-lived."}],"answer":"2"},{"id":131,"part":"C","unit":9,"blocks":[{"t":"p","h":"The table below gives different eras (Column X) and periods of the geological time scale (Column Y):"},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Ordovician","i. Mesozoic"],["B. Permian","ii. Cenozoic"],["C. Paleogene","iii. Paleozoic"],["D. Cretaceous",""]]},{"t":"p","h":"Which one of the following options represents all correct matches of Column X and Column Y?"}],"options":[{"key":"1","text":"A-i; B-ii; C-iii; D-ii"},{"key":"2","text":"A-iii; B-iii; C-ii; D-i"},{"key":"3","text":"A-ii; B-i; C-iii; D-iii"},{"key":"4","text":"A-ii; B-iii; C-i; D-i"}],"answer":"2"},{"id":132,"part":"C","unit":9,"blocks":[{"t":"p","h":"In a polluted aquatic environment, bacteria are chronically exposed to low concentrations of multiple antibiotics released from pharmaceutical effluents. Over time, resistant colonies appear even when the antibiotic concentration remains constant. To determine whether resistance arises through induced mutation (a physiological response to antibiotics) or random mutation followed by selection, an ecologist performs a fluctuation test similar to that of Luria and Delbrück (1943) using replicate bacterial cultures. Which one of the following outcomes would best support the conclusion that antibiotic resistance arises by random mutation followed by selection, rather than by induction?"}],"options":[{"key":"1","text":"Each replicate culture yields nearly the same number of resistant colonies after exposure to the antibiotic."},{"key":"2","text":"Different replicate cultures show large fluctuations in the number of resistant colonies, even though each was treated identically."},{"key":"3","text":"Resistant colonies appear only after antibiotic addition."},{"key":"4","text":"The number of resistant colonies increases predictably and proportionally with exposure time in every replicate culture."}],"answer":"2"},{"id":133,"part":"C","unit":9,"blocks":[{"t":"p","h":"In a monogamous haplodiploid social insect colony, sterile workers assist the queen in producing additional sisters instead of reproducing themselves. According to Hamilton's rule, altruistic behaviour is favoured when the genetic benefit to relatives (weighted by coefficient of relatedness, r) exceeds the cost, 'c' to the actor. If a worker helps the queen raise three daughters instead of producing two of her own, then based on Hamilton's rule, will helping behaviour evolve? [assume, genetic unit, which is the number of offsprings weighted by r as a measure of inclusive fitness]"}],"options":[{"key":"1","text":"Yes, because rb = 2.25 genetic units and c = 1 genetic unit"},{"key":"2","text":"No, because rb = 0.375 genetic units and c = 1 genetic unit"},{"key":"3","text":"Yes, but only if r &lt; 0.1 indicating weaker kin selection."},{"key":"4","text":"No, because kin selection cannot operate in haplodiploid species."}],"answer":"1"},{"id":134,"part":"C","unit":9,"blocks":[{"t":"p","h":"A certain trait in a species is governed by variation at the AB locus that has two alleles (A, B) that give rise to three genotypes, AA, AB and BB. A sample of 1000 individuals of the species were genotyped:"},{"t":"tbl","cls":"","rowHead":false,"head":[["Genotype","Number of individuals"]],"rows":[["AA","400"],["AB","400"],["BB","200"]]},{"t":"p","h":"Assume that each genotype is represented equally in males and females and mating is random. If the parents were randomly drawn from the sample of 1000 individuals given above, which one of the following options gives all correct values of the offspring genotype frequencies?"}],"options":[{"key":"1","text":"AA: 0.4; AB: 0.4; BB: 0.2"},{"key":"2","text":"AA: 0.6; AB: 0.2; BB: 0.2"},{"key":"3","text":"AA: 0.16; AB: 0.16; BB: 0.04"},{"key":"4","text":"AA: 0.36; AB: 0.48; BB: 0.16"}],"answer":"4"},{"id":135,"part":"C","unit":9,"blocks":[{"t":"p","h":"The table below lists conditions (Column X) and their evolutionary/behavioural outcome (Column Y)."},{"t":"tbl","cls":"match","rowHead":false,"head":[["Column X","Column Y"]],"rows":[["A. Cooperative breeding mediated by kin selection without physiological suppression of reproduction","i. Eusocial species such as naked mole rats"],["B. Hormonal reproductive suppression in nonbreeding females mediated by aggression","ii. High paternity certainty, low risk of cuckoldry"],["C. Biparental care","iii. Delayed dispersal and breeding of offspring such as in social birds"]]},{"t":"p","h":"Which one of the options below is a correct match between all terms of Column X and Column Y?"}],"options":[{"key":"1","text":"A-ii; B-i; C-iii"},{"key":"2","text":"A-i; B-ii; C-iii"},{"key":"3","text":"A-ii; B-iii; C-i"},{"key":"4","text":"A-iii; B-i; C-ii"}],"answer":"4"},{"id":136,"part":"C","unit":9,"blocks":[{"t":"p","h":"Which one of the following statements about evolution of the vertebrate brain is most accurate?"}],"options":[{"key":"1","text":"The relative size of the neocortex in primates is primarily determined by the absolute size of the brain and not by social or ecological pressures."},{"key":"2","text":"Increased brain size in birds and mammals is always accompanied by longer lifespans and slower reproductive rates, without exceptions."},{"key":"3","text":"Brain regions can evolve independently in response to specific ecological or behavioural demands, rather than all regions scaling uniformly with overall brain size."},{"key":"4","text":"The cerebellum, involved in motor coordination, has remained largely unchanged throughout vertebrate evolution because motor function is highly conserved."}],"answer":"3"},{"id":137,"part":"C","unit":8,"blocks":[{"t":"p","h":"The following statements are made regarding colchicine treatment in plants for inducing polyploidy:<br>A. In colchicine-treated cells, sister chromatids cannot separate during anaphase, leading to chromosome doubling when the nucleus reforms.<br>B. Colchicine stimulates endoreduplication in the treated cells, bypassing cytokinesis to yield polyploid cells in a process called \"C-mitosis\".<br>C. In sterile interspecific hybrids, colchicine treatment may restore fertility by converting them into amphipolyploids.<br>D. Colchicine treatment during meiosis has no effect, as it only acts on mitotic cells.<br>E. Colchicine binds to tubulin and prevents spindle fibre formation during mitosis.<br>Which one of the following options represents a combination of all correct statements?"}],"options":[{"key":"1","text":"A, C and E only"},{"key":"2","text":"B and C only"},{"key":"3","text":"A, B, C and E"},{"key":"4","text":"A, B, D and E"}],"answer":"1"},{"id":138,"part":"C","unit":13,"blocks":[{"t":"p","h":"The following statements are made regarding bioremediation and phytoremediation.<br>A. Phytovolatilization can reduce soil contamination but may create secondary pollution in the atmosphere.<br>B. In rhizofiltration, plants are effective only if their roots are exposed to contaminated soil.<br>C. Phytostabilization reduces contaminant mobility, but the total pollutant load in the soil remains unchanged.<br>D. Bioventing involves the injection of air or oxygen into soil to stimulate aerobic microbial degradation.<br>E. During in situ bioaugmentation, the remediation is achieved by physically removing contaminated soil for off-site treatment and replacing it with decontaminated soil.<br>Which one of the following options represents a combination of all INCORRECT statements?"}],"options":[{"key":"1","text":"B and E only"},{"key":"2","text":"B, C and E"},{"key":"3","text":"A, C and D"},{"key":"4","text":"A and D only"}],"answer":"1"},{"id":139,"part":"C","unit":13,"blocks":[{"t":"p","h":"Researchers attempted genetic manipulation of the metabolic pathway shown below for enhanced production of \"D\". However, increased expression of gene \"N\" did not result in increased production of \"D\" in any transgenic line. Levels of \"E\" were similar in transgenic as well as untransformed plants."},{"t":"img","src":"data:image/webp;base64,","w":287,"h":116,"alt":"Figure for question 139"},{"t":"p","h":"The following hypotheses were proposed for explaining the observed results:<br>A. Feedback inhibition of \"N\" by \"D\" B. Epistasis of gene N over gene M C. Substrate limitation for \"N\" D. Feedback inhibition of \"M\" by \"E\"<br>Which one of the following options lists all factors that, either independently or in combination, could explain the above results?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"A and C"},{"key":"3","text":"C and D"},{"key":"4","text":"B and D"}],"answer":"2"},{"id":140,"part":"C","unit":4,"blocks":[{"t":"p","h":"A B6 mouse (H-2ᵇ haplotype) was crossed with a CBA mouse (H-2ᵏ haplotype) to generate F1 progeny. The following skin transplant experiments were then performed:<br>A. Graft from B6 mouse to CBA mouse<br>B. Graft from F1 mouse to B6 parent<br>C. Graft from F1 mouse to CBA parent<br>D. Graft from F1 mouse to F1 mouse<br>E. Graft from B6 mouse to F1 mouse<br>Which one of the following options represents all recipients in which the graft is tolerated?"}],"options":[{"key":"1","text":"A"},{"key":"2","text":"B and C"},{"key":"3","text":"D"},{"key":"4","text":"D and E"}],"answer":"4"},{"id":141,"part":"C","unit":13,"blocks":[{"t":"p","h":"The following statements describe some of the features of Quartz Crystal Microbalance (QCM) biosensors:<br>A. A QCM biosensor is built with thin disc-shaped piezoelectric material which is connected to metal electrodes on the opposite faces.<br>B. If an AC voltage is applied on the quartz crystal, it produces an oscillation at a stable resonant frequency which is not determined by the applied AC voltage.<br>C. The surface of the quartz crystal is functionalized with a specific receptor that can bind to the target analyte.<br>D. As the mass on the surface of the crystal is increased, the resonant frequency of crystal increases in a predictable, quantitative way following Sauerbrey equation.<br>Which one of the following options represents a combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"B, C and D"},{"key":"3","text":"B and D only"},{"key":"4","text":"A and C only"}],"answer":"1"},{"id":142,"part":"C","unit":2,"blocks":[{"t":"p","h":"In standard or batch cultures, cells are grown in a fixed volume of medium. As they grow, nutrients are consumed and metabolites accumulate. Eventually, cultures may stop growing because of nutrient depletion and accumulation of toxic products. The following procedures may prolong the life of batch cultures:<br>A. Gradual addition of fresh medium and increasing volume of the culture<br>B. Replacing a constant fraction with an equal volume of fresh medium<br>C. Occasional removal of used medium and reducing growth factors in the medium<br>D. Intermittently adding serum and growth factors to the medium<br>Which one of the following combinations will ensure healthy growth of cells in culture?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"1"},{"id":143,"part":"C","unit":14,"blocks":[{"t":"p","h":"Some features of Transcranial Direct Current Stimulation (tDCS) are stated below:<br>A. The membrane potential of neurons is modulated by applying a weak electrical current between two electrodes placed on the scalp.<br>B. Neurons under the anode become depolarized, and neurons under the cathode become hyperpolarized during tDCS.<br>C. tDCS can disrupt neuronal activity and create a \"virtual lesion\" via anodal stimulation.<br>D. Neuronal activity is decreased in regions below the anode and increased in regions below the cathode.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"B, C and D"},{"key":"3","text":"C and D only"},{"key":"4","text":"A and B only"}],"answer":"4"},{"id":144,"part":"C","unit":14,"blocks":[{"t":"p","h":"Two Sanger sequencing reactions were carried out using the same DNA template and primer. The sequencing gels are shown below:"},{"t":"img","src":"data:image/webp;base64,","w":266,"h":191,"alt":"Figure for question 144"},{"t":"p","h":"Lane A of the reaction 2 gel shows the absence of lower bands and accumulation of higher bands (represented by a black thick band). The following reasons are predicted:<br>A. The template DNA does not contain the base A near its 5’-region.<br>B. The processivity of the Sequenase enzyme is very high.<br>C. In the second reaction, the concentration of ddATP is very low.<br>D. In the second reaction, the concentration of ddTTP is very high.<br>Which one of the following options represents the correct reason(s)?"}],"options":[{"key":"1","text":"A, B, and D"},{"key":"2","text":"B and C"},{"key":"3","text":"D only"},{"key":"4","text":"C only"}],"answer":"4"},{"id":145,"part":"C","unit":14,"blocks":[{"t":"p","h":"Dynamic Light Scattering measurements of a protein encapsulated inside AOT/isooctane reverse micelles suspended in n-heptane at 10 °C and 1 atm show an average hydrodynamic diameter of 17 nm, while the empty micelles have an average diameter of 11 nm. Calculate the approximate hydrodynamic radius of the encapsulated protein, assuming spherical geometry of the protein and the reverse micelle and that the protein only occupies the aqueous core of the micelle"}],"options":[{"key":"1","text":"8.60 nm"},{"key":"2","text":"7.60 nm"},{"key":"3","text":"3.00 nm"},{"key":"4","text":"6.60 nm"}],"answer":"2"}];
